def compute_cap_tax(pricing_out: dict) -> dict:
    gross = int(pricing_out['gross_cents'])
    encoder_bits = int(pricing_out.get('encoder_bits', 0))
    bit_budget_b = 1
    return {
        'tax_reserve_cents': (gross * 90) // 990,
        'encoder_bits': encoder_bits,
        'bit_budget_b': bit_budget_b,
        'channel_capacity_s': 1 << bit_budget_b,
    }

